window.WORLDSCOPE_PLACES = [{"id": "petra", "name": "Petra", "wiki": "Petra", "country": "Jordan", "category": "history", "tag": "ANCIENT WONDER", "lat": 30.3285, "lon": 35.4444, "height": 15000, "source": "https://en.wikipedia.org/wiki/Petra", "summary": "Petra is an ancient city and archaeological site in southern Jordan. Famous for its rock-cut architecture and water conduit systems, Petra is also called the \"Rose City\" because of the colour of the sandstone from which it is carved. The city is one of the New 7 Wonders of the World and a UNESCO World Heritage Site.", "description": "Ancient rock-cut historical city in Jordan", "wikibase": "Q5788", "image": "./assets/petra.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Al_Deir_Petra.JPG", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Al_Deir_Petra.JPG/330px-Al_Deir_Petra.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Azurfrog · CC BY-SA 3.0"}, {"id": "kyoto", "name": "Kyoto", "wiki": "Kyoto", "country": "Japan", "category": "city", "tag": "CULTURE & CALM", "lat": 35.0116, "lon": 135.7681, "height": 45000, "source": "https://en.wikipedia.org/wiki/Kyoto", "summary": "Kyoto, officially Kyoto City , is the capital city of Kyoto Prefecture in the Kansai region of Japan's largest and most populous island of Honshu. As of 2020, the city had a population of 1.46 million, making it the ninth-most populous city in Japan. More than half (56.8%) of Kyoto Prefecture's population resides in the city. The city is the cultural anchor of the substantially larger Greater Kyoto, a metropolitan statistical area home to approximately 3.8 million people. It is also part of the even larger Keihanshin metropolitan area, along with Osaka and Kobe.", "description": "City in the Kansai region of Japan", "wikibase": "Q34600", "image": "./assets/kyoto.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Kiyomizu-dera,_Kyoto,_November_2016_-02.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Kiyomizu-dera%2C_Kyoto%2C_November_2016_-02.jpg/330px-Kiyomizu-dera%2C_Kyoto%2C_November_2016_-02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Martin Falbisoner · CC BY-SA 4.0"}, {"id": "grand-canyon", "name": "Grand Canyon", "wiki": "Grand Canyon", "country": "United States", "category": "nature", "tag": "NATURAL WONDER", "lat": 36.1069, "lon": -112.1129, "height": 70000, "source": "https://en.wikipedia.org/wiki/Grand_Canyon", "summary": "The Grand Canyon is a steep-sided canyon carved by the Colorado River in Arizona, United States. The Grand Canyon is 277 miles (446 km) long, up to 18 miles (29 km) wide and attains a depth of over a mile.", "description": "Steep-sided canyon in Arizona, US", "wikibase": "Q118841", "image": "./assets/grand-canyon.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Canyon_River_Tree_(165872763).jpeg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Canyon_River_Tree_%28165872763%29.jpeg/330px-Canyon_River_Tree_%28165872763%29.jpeg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Lennart Sikkema · CC BY 3.0"}, {"id": "citadel-of-erbil", "name": "Erbil Citadel", "wiki": "Citadel of Erbil", "country": "Kurdistan Region · Iraq", "category": "history", "tag": "LAYERS OF HISTORY", "lat": 36.1912, "lon": 44.0092, "height": 7000, "source": "https://en.wikipedia.org/wiki/Citadel_of_Erbil", "summary": "The Citadel of Erbil, locally called Qellat, is a tell or occupied mound, and the historical city centre of Erbil in the Kurdistan Region of Iraq. The citadel was added to the World Heritage List on 21 June 2014.", "description": "Citadel and archaeological settlement hill in Erbil, Iraqi Kurdistan", "wikibase": "Q206236", "image": "./assets/citadel-of-erbil.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Hawler_Castle.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Hawler_Castle.jpg/330px-Hawler_Castle.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "jan kurdistani · CC BY-SA 2.0"}, {"id": "giza-pyramid-complex", "name": "The Pyramids of Giza", "wiki": "Giza pyramid complex", "country": "Egypt", "category": "history", "tag": "ANCIENT WONDER", "lat": 29.9792, "lon": 31.1342, "height": 12000, "source": "https://en.wikipedia.org/wiki/Giza_pyramid_complex", "summary": "The Giza pyramid complex in Egypt is home to the Great Pyramid, the pyramid of Khafre, and the pyramid of Menkaure, along with their associated pyramid complexes and the Great Sphinx. All were built during the Fourth Dynasty of the Old Kingdom of ancient Egypt, between c. 2600 – c. 2500 BC. The site also includes several temples, cemeteries, and the remains of a workers' village.", "description": "Archaeological site near Cairo, Egypt", "wikibase": "Q12508", "image": "./assets/giza-pyramid-complex.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Pyramids_of_the_Giza_Necropolis.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Pyramids_of_the_Giza_Necropolis.jpg/330px-Pyramids_of_the_Giza_Necropolis.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "KennyOMG · CC BY-SA 4.0"}, {"id": "machu-picchu", "name": "Machu Picchu", "wiki": "Machu Picchu", "country": "Peru", "category": "history", "tag": "ABOVE THE CLOUDS", "lat": -13.1631, "lon": -72.545, "height": 14000, "source": "https://en.wikipedia.org/wiki/Machu_Picchu", "summary": "Machu Picchu is a 15th-century Inca citadel located in the Eastern Cordillera of southern Peru on a mountain ridge at 2,430 meters (7,970 ft). It is situated in the Machupicchu District of Urubamba Province about 80 kilometers northwest of Cusco, above the Sacred Valley and along the Urubamba River, which forms a deep canyon with a subtropical mountain climate.", "description": "15th-century Inca citadel in Peru", "wikibase": "Q676203", "image": "./assets/machu-picchu.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Machu_Picchu,_2023_(012).jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Machu_Picchu%2C_2023_%28012%29.jpg/330px-Machu_Picchu%2C_2023_%28012%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Draceane · CC BY-SA 4.0"}, {"id": "mount-everest", "name": "Mount Everest", "wiki": "Mount Everest", "country": "Nepal · China", "category": "nature", "tag": "THE ROOF OF THE WORLD", "lat": 27.9881, "lon": 86.925, "height": 60000, "source": "https://en.wikipedia.org/wiki/Mount_Everest", "summary": "Mount Everest is the highest mountain on Earth above sea level. It lies in the Mahalangur Himal sub-range of the Himalayas and marks part of the China–Nepal border at its summit. Its height was most recently measured in 2020 through a joint survey by Nepalese and Chinese authorities as 8,848.86 m.", "description": "Earth's highest mountain", "wikibase": "Q513", "image": "./assets/mount-everest.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Mt._Everest_from_Gokyo_Ri_November_5,_2012.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Mt._Everest_from_Gokyo_Ri_November_5%2C_2012.jpg/330px-Mt._Everest_from_Gokyo_Ri_November_5%2C_2012.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Rdevany · CC BY-SA 3.0"}, {"id": "rome", "name": "Rome", "wiki": "Rome", "country": "Italy", "category": "city", "tag": "THE ETERNAL CITY", "lat": 41.9028, "lon": 12.4964, "height": 42000, "source": "https://en.wikipedia.org/wiki/Rome", "summary": "Rome is the capital and largest city of Italy. It is also the administrative centre of the Lazio region and of the Metropolitan City of Rome. A special municipality named Roma Capitale with a population of 2.7 million in an area of 1,287.36 km2 (497.1 mi2), Rome is the third most populous city in the European Union by population within city limits. The Metropolitan City of Rome Capital, with a population of 4.2 million, is the most populous metropolitan city in Italy. Its metropolitan area is the third-most populous within Italy. Rome is located in the central-western portion of the Italian Peninsula, within Lazio (Latium), along the shores of the Tiber Valley. Vatican City—the smallest country in the world and headquarters of the worldwide Catholic Church under the governance of the Holy See—is an independent country within Rome's municipal boundaries, the only existing example of a country within a city. Rome is often referred to as the \"City of Seven Hills\" due to its geography, and also as the \"Eternal City\". Rome is generally considered to be one of the cradles of Western civilization and Western Christian culture.", "description": "Capital and largest city of Italy", "wikibase": "Q220", "image": "./assets/rome.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Trevi_Fountain,_Rome,_Italy_2_-_May_2007.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Trevi_Fountain%2C_Rome%2C_Italy_2_-_May_2007.jpg/330px-Trevi_Fountain%2C_Rome%2C_Italy_2_-_May_2007.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Diliff · CC BY 3.0"}, {"id": "istanbul", "name": "Istanbul", "wiki": "Istanbul", "country": "Türkiye", "category": "city", "tag": "WHERE WORLDS MEET", "lat": 41.0082, "lon": 28.9784, "height": 50000, "source": "https://en.wikipedia.org/wiki/Istanbul", "summary": "Istanbul is the largest city in Turkey, a megacity, constituting the country's economic, cultural, and historical center. With a population of over 15 million, it is home to 18% of the population of Turkey. Istanbul is among the largest cities in Europe and in the world by population. It is a city on two continents; about two-thirds of its population live in Europe and the rest in Asia. Istanbul straddles the Bosphorus – one of the world's busiest waterways – in northwestern Turkey, between the Sea of Marmara and the Black Sea. Its area of 5,461 square kilometers (2,109 mi2) is coterminous with Istanbul Province.", "description": "Largest city in Turkey", "wikibase": "Q406", "image": "./assets/istanbul.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Historical_peninsula_and_modern_skyline_of_Istanbul.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Historical_peninsula_and_modern_skyline_of_Istanbul.jpg/330px-Historical_peninsula_and_modern_skyline_of_Istanbul.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Hunanuk · CC0"}, {"id": "great-barrier-reef", "name": "Great Barrier Reef", "wiki": "Great Barrier Reef", "country": "Australia", "category": "nature", "tag": "AN OCEAN OF LIFE", "lat": -18.2871, "lon": 147.6992, "height": 350000, "source": "https://en.wikipedia.org/wiki/Great_Barrier_Reef", "summary": "The Great Barrier Reef is the world's largest coral reef system, composed of over 2,900 individual reefs and 900 islands stretching for over 2,300 kilometres (1,400 mi) over an area of approximately 344,400 square kilometres (133,000 mi2). The reef is located in the Coral Sea, off the coast of Queensland, Australia. It is separated from the coast by a channel 160 kilometres (100 mi) wide in places and over 61 metres (200 ft) deep. The Great Barrier Reef can be seen from outer space and is the world's biggest single structure made by living organisms. This reef structure is composed of and built by billions of tiny organisms, known as coral polyps. It supports a wide diversity of life and was selected as a World Heritage Site in 1981. CNN labelled it one of the Seven Natural Wonders of the World in 1997. Australian World Heritage places included it in its list in 2007. The Queensland National Trust named it a state icon of Queensland in 2006.", "description": "Coral reef system in Queensland, Australia", "wikibase": "Q7343", "image": "./assets/great-barrier-reef.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:ISS-45_StoryOfWater,_Great_Barrier_Reef,_Australia.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/ISS-45_StoryOfWater%2C_Great_Barrier_Reef%2C_Australia.jpg/330px-ISS-45_StoryOfWater%2C_Great_Barrier_Reef%2C_Australia.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "NASA/Kjell Lindgren · Public domain"}, {"id": "serengeti-national-park", "name": "Serengeti", "wiki": "Serengeti National Park", "country": "Tanzania", "category": "nature", "tag": "INTO THE WILD", "lat": -2.3333, "lon": 34.8333, "height": 150000, "source": "https://en.wikipedia.org/wiki/Serengeti_National_Park", "summary": "The Serengeti National Park is a large national park in northern Tanzania that stretches over 14,763 km2 (5,700 sq mi). It is located in eastern Mara Region and northeastern Simiyu Region and contains over 15,000 km2 (5,800 sq mi) of savanna. The park was established in 1940.", "description": "National park in Tanzania", "wikibase": "Q11812902", "image": "./assets/serengeti-national-park.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Serengeti-Landscape-2012.JPG", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Serengeti-Landscape-2012.JPG/330px-Serengeti-Landscape-2012.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Bjørn Christian Tørrissen · CC BY-SA 3.0"}, {"id": "angkor-wat", "name": "Angkor Wat", "wiki": "Angkor Wat", "country": "Cambodia", "category": "history", "tag": "A KINGDOM IN STONE", "lat": 13.4125, "lon": 103.867, "height": 12000, "source": "https://en.wikipedia.org/wiki/Angkor_Wat", "summary": "Angkor Wat is a Theravada Buddhist temple complex, originally built as a Vaishnava Hindu temple, in Siem Reap, Cambodia. It is the largest religious complex in the world. Located on a site measuring 162.6 hectares within the medieval capital of Angkor, it was constructed between 1113 and 1150 CE during the reign of the Khmer king Suryavarman II as a Hindu temple dedicated to Vishnu. From the late 13th century onward, the complex was gradually transformed into a Buddhist temple as Khmer kings adopted Buddhism. Angkor Wat has remained a Buddhist monastery and an active center of Buddhist worship into the present day. It is noted for its monumental scale and extensive bas-reliefs and an architectural unity characteristic of Khmer architecture. Unlike most Angkorian temples, it is oriented toward the west. It is a symbol of Cambodia and appears on the Cambodian national flag.", "description": "Buddhist temple complex in Cambodia", "wikibase": "Q43473", "image": "./assets/angkor-wat.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Angkor_Wat.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Angkor_Wat.jpg/330px-Angkor_Wat.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Bjørn Christian Tørrissen · CC BY-SA 4.0"}, {"id": "tokyo", "name": "Tokyo", "wiki": "Tokyo", "country": "Japan", "category": "city", "tag": "AFTER DARK", "lat": 35.6762, "lon": 139.6503, "height": 55000, "source": "https://en.wikipedia.org/wiki/Tokyo", "summary": "Tokyo, officially the Tokyo Metropolis, is the capital and most populous city of Japan. The population of the city proper was over 14 million as of 2023. The Greater Tokyo Area, which includes Tokyo and parts of six neighboring prefectures, is the third-most populous metropolitan area in the world, with 33 million residents as of 2025.", "description": "Capital and most populous city of Japan", "wikibase": "Q1490", "image": "./assets/tokyo.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Skyscrapers_of_Shinjuku_2009_January.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/Skyscrapers_of_Shinjuku_2009_January.jpg/330px-Skyscrapers_of_Shinjuku_2009_January.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Morio · CC BY-SA 3.0"}, {"id": "paris", "name": "Paris", "wiki": "Paris", "country": "France", "category": "city", "tag": "THE CITY OF LIGHT", "lat": 48.8566, "lon": 2.3522, "height": 40000, "source": "https://en.wikipedia.org/wiki/Paris", "summary": "Paris is the capital and largest city of France, with an estimated city population of 2.04 million in an area of 105.4 km2 (40.7 sq mi), as of January 2026, and a metropolitan population of 13.3 million (2023). Located on the Seine in the centre of the Île-de-France region, it is the largest metropolitan area and fourth-most populous city in the European Union (EU). Paris is nicknamed the \"City of Light\" mainly due to its leading role in the Age of Enlightenment.", "description": "Capital and largest city of France", "wikibase": "Q90", "image": "./assets/paris.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:La_Tour_Eiffel_vue_de_la_Tour_Saint-Jacques,_Paris_ao%C3%BBt_2014_(2).jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/La_Tour_Eiffel_vue_de_la_Tour_Saint-Jacques%2C_Paris_ao%C3%BBt_2014_%282%29.jpg/330px-La_Tour_Eiffel_vue_de_la_Tour_Saint-Jacques%2C_Paris_ao%C3%BBt_2014_%282%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Yann Caradec from Paris, France · CC BY-SA 2.0"}, {"id": "new-york-city", "name": "New York City", "wiki": "New York City", "country": "United States", "category": "city", "tag": "NEVER STANDING STILL", "lat": 40.7128, "lon": -74.006, "height": 50000, "source": "https://en.wikipedia.org/wiki/New_York_City", "summary": "New York, often called New York City (NYC), is the most populous city in the United States. It is located at the southern tip of New York State on New York Harbor, one of the world's largest natural harbors. The city comprises five boroughs—Manhattan, Brooklyn, Queens, the Bronx, and Staten Island—each being coextensive with its respective county. It is the geographical and demographic center of both the Northeast megalopolis and the New York metropolitan area, the largest metropolitan area in the United States by both population and urban area. New York is a global center of technology, finance, commerce, culture, entertainment and media, academics and scientific output, the arts and fashion—and as home to the headquarters of the United Nations, international diplomacy. New York City is known for its fast pace and continuous urban energy.", "description": "Most populous city in the United States", "wikibase": "Q60", "image": "./assets/new-york-city.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:View_of_Empire_State_Building_from_Rockefeller_Center_New_York_City_dllu_(cropped).jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/View_of_Empire_State_Building_from_Rockefeller_Center_New_York_City_dllu_%28cropped%29.jpg/330px-View_of_Empire_State_Building_from_Rockefeller_Center_New_York_City_dllu_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Dllu · CC BY-SA 4.0"}, {"id": "kirkjufell", "name": "Kirkjufell", "wiki": "Kirkjufell", "country": "Iceland", "category": "nature", "tag": "FIRE & ICE", "lat": 64.9244, "lon": -23.3122, "height": 18000, "source": "https://en.wikipedia.org/wiki/Kirkjufell", "summary": "Kirkjufell is a 463 m high hill on the north coast of Iceland's Snæfellsnes peninsula, near the town of Grundarfjörður. It is claimed to be the most photographed mountain in the country. Kirkjufell was one of the filming locations for Game of Thrones season 6 and 7, featuring as the \"arrowhead mountain\" that the Hound and the company north of the Wall see when capturing a wight.", "description": "Mountain in Iceland", "wikibase": "Q1547402", "image": "./assets/kirkjufell.jpg", "photoSource": "https://commons.wikimedia.org/wiki/File:Kirkjufell_in_Iceland.jpg", "remoteImage": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Kirkjufell_in_Iceland.jpg/330px-Kirkjufell_in_Iceland.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "photoCredit": "Anjali Kiggal · CC BY-SA 4.0"}];
